--- a/internal/cli/patterns/runs.go
+++ b/internal/cli/patterns/runs.go
@@ -21,7 +21,7 @@ import (
 // IndexerVersion identifies the corpus indexer that produced a build; bump it
 // when extraction/classification output changes so consumers can detect stale
 // corpora.
-const IndexerVersion = 10
+const IndexerVersion = 11

 const RunsRelPath = "patterns/runs.ndjson"
 const patternRunsKeep = 50

1	package cli
2	
3	import (
4		"encoding/json"
5		"path"
6		"regexp"
7		"sort"
8		"strings"
9	
10		clibase "github.com/entireio/entire-brain/internal/cli/internal/base"
11		"github.com/entireio/entire-brain/internal/cli/internal/factstore"
12		patterncore "github.com/entireio/entire-brain/internal/cli/patterns"
13	)
14	
15	// Pattern corpus enrichment (V2, Phase 2): turn episodes into brain events by
16	// linking the operational evidence — command exit/failure, files touched,
17	// way-of-working meta hits, and durable-fact links — so Phase 3 candidates can be
18	// corroborated across intent + method + evidence + outcome. All deterministic and
19	// token-free; missing optional sources (facts, semantic) degrade to empty.
20	
21	type corpusCommand struct {
22		head     string
23		raw      string
24		line     int
25		callID   string
26		exitCode *int
27		failed   bool
28	}
29	
30	type corpusFileRef struct {
31		path   string
32		action string // read | write | edit | add | delete
33		line   int
34	}
35	
36	var (
37		reExitCode  = regexp.MustCompile(`(?i)(?:exited with code|exit code:?)\s*(\d+)`)
38		rePatchFile = regexp.MustCompile(`(?m)^\*\*\* (Add|Update|Delete) File: (.+)$`)
39		// git commit confirmation: "[branch hash] subject" — local evidence only.
40		reCommitConfirm = regexp.MustCompile(`\[([A-Za-z0-9._/+-]+) ([0-9a-f]{7,40})\] (.+)`)
41	)
42	
43	type corpusCommit struct {
44		hash, branch, subject string
45		line                  int
46	}
47	
48	// corpusCommits extracts git commits an episode landed from the local
49	// `[branch hash] subject` confirmation lines in its work text. No network; the
50	// subject is redacted and truncated.
51	func corpusCommits(workText string) []corpusCommit {
52		seen := map[string]bool{}
53		var out []corpusCommit
54		for i, line := range strings.Split(workText, "\n") {
55			m := reCommitConfirm.FindStringSubmatch(line)
56			if m == nil {
57				continue
58			}
59			hash := m[2]
60			if seen[hash] {
61				continue
62			}
63			seen[hash] = true
64			out = append(out, corpusCommit{
65				hash:    hash,
66				branch:  m[1],
67				subject: clibase.RedactText(clibase.TruncateString(strings.TrimSpace(m[3]), 160)),
68				line:    i + 1,
69			})
70		}
71		return out
72	}
73	
74	// claudeFileTools maps Claude/pi file tool names to a file action.
75	var claudeFileTools = map[string]string{
76		"read": "read", "view": "read", "cat": "read",
77		"write": "write", "create": "write",
78		"edit": "edit", "str_replace": "edit", "str_replace_editor": "edit", "apply_patch": "edit",
79	}
80	
81	// corpusEpisodeOps extracts ordered tool calls, shell commands (with exit/failure
82	// correlated by call id), and file references from one episode's work segment.
83	func corpusEpisodeOps(workText string) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
84		exitByCall := map[string]int{}
85		for i, line := range strings.Split(workText, "\n") {
86			line = strings.TrimSpace(line)
87			if !strings.HasPrefix(line, "{") {
88				continue
89			}
90			var obj map[string]any
91			if json.Unmarshal([]byte(line), &obj) != nil {
92				continue
93			}
94			ln := i + 1
95			switch jsonString(obj["type"]) {
96			case "response_item":
97				p := jsonMap(obj["payload"])
98				switch jsonString(p["type"]) {
99				case "function_call":
100					name := strings.ToLower(strings.TrimSpace(jsonString(p["name"])))
101					tools = append(tools, corpusToolOp{name: name, line: ln})
102					if cmd := shellCommandFromInput(name, p["arguments"]); cmd != "" {
