305	// linkEpisodeFacts links an episode to active durable facts on its branch whose
306	// text/locus overlaps the episode's intent terms and file basenames. Capped;
307	// branch-scoped so facts never leak across branches.
308	func linkEpisodeFacts(facts []factRecord, intent string, files []corpusFileRef) []corpusFactLink {
309		if len(facts) == 0 {
310			return nil
311		}
312		terms := map[string]bool{}
313		for _, t := range brainBriefFileMatchTerms(intent) {
314			terms[t] = true
315		}
316		for _, f := range files {
317			base := strings.ToLower(path.Base(f.path))
318			base = strings.TrimSuffix(base, path.Ext(base))
319			if len(base) >= 3 {
320				terms[base] = true
321			}
322		}
323		if len(terms) == 0 {
324			return nil
325		}
326		type scored struct {
327			f       factRecord
328			overlap int
329		}
330		var matched []scored
331		for _, f := range facts {
332			if f.Status != "active" {
333				continue
334			}
335			overlap := 0
336			seen := map[string]bool{}
337			for _, w := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(f.Text), -1) {
338				if terms[w] && !seen[w] {
339					seen[w] = true
340					overlap++
341				}
342			}
343			for _, l := range f.Locus {
344				if terms[strings.ToLower(l)] {
345					overlap += 2 // locus match is stronger evidence
346				}
347			}
348			if overlap > 0 {
349				matched = append(matched, scored{f, overlap})
350			}
351		}
352		sort.SliceStable(matched, func(i, j int) bool { return matched[i].overlap > matched[j].overlap })
353		var out []corpusFactLink
354		for _, m := range matched {
355			if len(out) >= 5 {
356				break
357			}
358			out = append(out, corpusFactLink{factID: m.f.ID, branch: m.f.Branch, kind: factstore.KindOrInferred(m.f), paths: strings.Join(m.f.Paths, ","), weight: float64(m.overlap)})
359		}
360		return out
361	}
